#' FoodNet Trends Pipeline Progress Tracking Utilities
#'
#' This file contains functions for tracking and displaying progress in the 
#' pathogen analysis pipeline using a milestone-based approach that is 
#' lightweight but still provides meaningful feedback to users.
#'
#' @author Generated by Claude
#' @version 1.0
#' @date 2025-05-21

#' Define analysis milestones with expected percentages
#' These values represent the standard progression of a pathogen analysis
analysis_milestones <- list(
  "SETUP" = 0,
  "DATA_LOADING" = 5,
  "DATA_VALIDATION" = 10,
  "PREPROCESSING" = 15,
  "FILTERING" = 20,
  "DATA_JOINING" = 25,
  "MODEL_PREPARATION" = 30,
  "MODEL_START" = 40,
  "MODEL_RUNNING_25" = 45,
  "MODEL_RUNNING_50" = 50,
  "MODEL_RUNNING_75" = 55,
  "MODEL_COMPLETE" = 60,
  "IR_CALCULATION" = 70,
  "IRR_CALCULATION" = 80,
  "VISUALIZATION" = 90,
  "SUMMARY" = 95,
  "COMPLETE" = 100
)

#' Calculate progress stage for MCMC iterations
#'
#' This function calculates the appropriate milestone to report based on
#' current MCMC progress to provide feedback during the longest part of analysis.
#'
#' @param current_iter The current MCMC iteration
#' @param total_iter The total number of MCMC iterations
#' @param current_chain The current chain number
#' @param total_chains The total number of chains
#' @return The appropriate milestone string
get_model_milestone <- function(current_iter, total_iter, current_chain, total_chains) {
  # Calculate overall progress through all chains (0-1)
  progress <- ((current_chain - 1) + (current_iter / total_iter)) / total_chains
  
  if (progress < 0.25) {
    return("MODEL_START")
  } else if (progress < 0.5) {
    return("MODEL_RUNNING_25")
  } else if (progress < 0.75) {
    return("MODEL_RUNNING_50")
  } else if (progress < 1.0) {
    return("MODEL_RUNNING_75")
  } else {
    return("MODEL_COMPLETE")
  }
}

#' Tracking state for the progress tracking system
progress_state <- new.env()
progress_state$last_milestone <- NULL
progress_state$start_time <- Sys.time()
progress_state$pathogen <- "UNKNOWN"

#' Initialize progress tracking
#'
#' @param pathogen The name of the pathogen being analyzed
#' @return None, called for side effects
initialize_progress <- function(pathogen) {
  progress_state$pathogen <- pathogen
  progress_state$start_time <- Sys.time()
  progress_state$last_milestone <- NULL
}

#' Format elapsed time in a human-readable format
#'
#' @param seconds The number of seconds elapsed
#' @return A formatted string like "1h 23m 45s"
format_elapsed_time <- function(seconds) {
  hours <- floor(seconds / 3600)
  minutes <- floor((seconds - hours * 3600) / 60)
  secs <- floor(seconds - hours * 3600 - minutes * 60)
  
  if (hours > 0) {
    return(sprintf("%dh %dm %ds", hours, minutes, secs))
  } else if (minutes > 0) {
    return(sprintf("%dm %ds", minutes, secs))
  } else {
    return(sprintf("%ds", secs))
  }
}

#' Estimate remaining time based on current progress
#'
#' @param percentage The current percentage of completion
#' @return A formatted string with estimated remaining time
estimate_remaining_time <- function(percentage) {
  if (percentage <= 0 || percentage >= 100) return("--")
  
  elapsed_seconds <- as.numeric(difftime(Sys.time(), progress_state$start_time, units = "secs"))
  if (elapsed_seconds < 1) return("calculating...")
  
  # Estimate total time based on current progress
  total_time_estimate <- elapsed_seconds / (percentage / 100)
  remaining_seconds <- total_time_estimate - elapsed_seconds
  
  # Format the remaining time
  format_elapsed_time(remaining_seconds)
}

#' Log progress with a milestone-based progress bar
#'
#' This function logs messages and displays a progress bar based on predefined
#' milestones. It tracks the progression of analysis and shows estimated time.
#' Enhanced to be environment-agnostic by writing to both console and file.
#'
#' @param stage The current processing stage label
#' @param message Optional message to display
#' @param milestone The current milestone (from analysis_milestones)
#' @param ... Additional arguments passed to cat()
#' @return None, called for side effects
log_progress <- function(stage, message=NULL, milestone=NULL, ...) {
  timestamp <- format(Sys.time(), "[%Y-%m-%d %H:%M:%S]")
  
  # Get progress percentage from milestone if provided
  progress_pct <- NULL
  if (!is.null(milestone) && milestone %in% names(analysis_milestones)) {
    progress_pct <- analysis_milestones[[milestone]]
    progress_state$last_milestone <- milestone
  } else if (!is.null(progress_state$last_milestone)) {
    # Use the last milestone if none provided
    progress_pct <- analysis_milestones[[progress_state$last_milestone]]
  }
  
  # Format elapsed time
  elapsed_seconds <- as.numeric(difftime(Sys.time(), progress_state$start_time, units = "secs"))
  elapsed_str <- format_elapsed_time(elapsed_seconds)
  
  # Try multiple directory paths to find a writable location
  # We'll try current directory, then work subdirectories
  directories_to_try <- c(
    ".",                # Try current directory first
    "./work",          # Try work subdirectory
    "./logs",          # Try logs subdirectory
    "/tmp"             # Try temporary directory as last resort
  )
  
  # Try to write to the first writable directory
  progress_file <- NULL
  for (dir in directories_to_try) {
    # Create test filename in this directory
    test_file <- file.path(dir, paste0("test_", Sys.getpid(), ".txt"))
    
    # Check if we can write to this directory
    can_write <- tryCatch({
      # Try to write a test file
      writeLines("test", test_file)
      # If successful, clean it up
      if (file.exists(test_file)) file.remove(test_file)
      TRUE
    }, error = function(e) {
      FALSE
    })
    
    if (can_write) {
      # Use this directory for our progress files
      progress_file <- file.path(dir, paste0(progress_state$pathogen, "_progress.txt"))
      log_file <- file.path(dir, paste0(progress_state$pathogen, "_progress_log.txt"))
      percent_file <- file.path(dir, paste0(progress_state$pathogen, "_percent.txt"))
      break
    }
  }
  
  # If we couldn't find a writable directory, default to current directory
  if (is.null(progress_file)) {
    progress_file <- paste0(progress_state$pathogen, "_progress.txt")
    log_file <- paste0(progress_state$pathogen, "_progress_log.txt")
    percent_file <- paste0(progress_state$pathogen, "_percent.txt")
  }
  
  # Create progress string if we have a percentage
  progress_str <- ""
  if (!is.null(progress_pct)) {
    width <- 40
    filled <- round(width * (progress_pct / 100))
    
    # Estimate remaining time
    eta <- estimate_remaining_time(progress_pct)
    
    # Create the progress bar - simpler ASCII version for cross-environment compatibility
    bar <- paste0(
      "\n[", 
      strrep("#", filled),
      strrep(".", max(0, width - filled)),
      "] ", 
      sprintf("%3d%%", progress_pct),
      " | ", progress_state$pathogen,
      " | Elapsed: ", elapsed_str,
      " | ETA: ", eta
    )
    progress_str <- bar
    
    # Write to progress file (overwrite previous content)
    tryCatch({
      # Write basic progress information to file - helps with monitoring
      progress_data <- c(
        paste0("PATHOGEN: ", progress_state$pathogen),
        paste0("STAGE: ", stage),
        paste0("PROGRESS: ", progress_pct, "%"),
        paste0("MESSAGE: ", if(is.null(message)) "-" else message),
        paste0("ELAPSED: ", elapsed_str),
        paste0("REMAINING: ", eta),
        paste0("TIMESTAMP: ", timestamp),
        if(!is.null(milestone)) paste0("MILESTONE: ", milestone) else NULL
      )
      writeLines(progress_data, progress_file)
      
      # Also write a simple progress status file - only contains percentage (easy to monitor)
      writeLines(as.character(progress_pct), percent_file)
    }, error = function(e) {
      # Silent failure - we don't want to disrupt processing if writing progress fails
      # Just log to console in case of debugging
      cat("Note: Could not write progress file: ", e$message, "\n")
    })
  }
  
  # Create a clear headline message to stand out in logs
  headline <- paste0(
    "\n=========================================\n",
    "  PATHOGEN: ", progress_state$pathogen, 
    if(!is.null(progress_pct)) paste0(" [", progress_pct, "%]") else "",
    "\n  STAGE: ", stage,
    "\n  ", timestamp,
    "\n=========================================")
  
  # Combine all parts and print - use multiple approaches for compatibility
  full_message <- if (!is.null(message)) {
    sprintf("%s\n%s: %s%s", headline, stage, message, progress_str)
  } else {
    sprintf("%s\n%s%s", headline, stage, progress_str)
  }
  
  # Print to console
  cat(full_message, "\n", ...)
  flush.console()
  
  # Also write to a separate log file that can be monitored
  tryCatch({
    log_file <- paste0(progress_state$pathogen, "_progress_log.txt")
    cat(full_message, "\n", file = log_file, append = TRUE)
  }, error = function(e) {
    # Silent fail - don't disrupt processing for logging
  })
}

#' Standard log message function without progress tracking
#' For backward compatibility with existing code
#'
#' @param stage The current processing stage label
#' @param message Optional message to display
#' @param ... Additional arguments passed to cat()
#' @return None, called for side effects
log_message <- function(stage, message=NULL, ...) {
  timestamp <- format(Sys.time(), "[%Y-%m-%d %H:%M:%S]")
  if (!is.null(message)) {
    cat(sprintf("%s %s: %s\n", timestamp, stage, message), ...)
  } else {
    cat(sprintf("%s %s\n", timestamp, stage), ...)
  }
  flush.console()
}